additionalDataKeys.postFuncBody:
let color = '#f16362';
if (typeof value !== undefined) {
    if (value === "insideRestrictedZone") {
        color = '#DD2C00;#6F1600';
    }
    if (value === "insideUnloadingZone") {
        color = '#1EBB4D;#0F5E27';
    }
    if (value === "insideLoadingZone") {
        color = '#3388FF;#1A4480';
    }
    if (value === "outsideMineSite") {
        color = '#6D6D6D;#373737';
    }
}
return color;

label.patternFunction:
let textColor = data.geoStatusColor.split(';')[1];
return `<div style="position: relative; white-space: nowrap; text-align: center;">
          <div style="
              border: 1px solid ${textColor};
              border-radius: 8px;
              background-color: #ffffff;
              padding: 8px;
              color: ${textColor}">
                <span style="
                  font-size: 14px;
                  font-weight: 500;
                  line-height: 20px;
                  margin-bottom: 4px;">
                    ${data.entityName}
                </span>
          </div>
        </div>`;

tooltip.patternFunction:
const speedUnit = {
  from: 'mph',
  METRIC: 'km/h',
  IMPERIAL: 'mph',
  HYBRID: 'km/h'
};

const usrSpeedUnit = ctx.unitService.getTargetUnitSymbol(speedUnit);

const speedValue = ctx.unitService.convertUnitValue(data?.speed || 0, speedUnit).toFixed(1);

const loadWeightUnit = {
  from: 'lb',
  METRIC: 't',
  IMPERIAL: 'lb',
  HYBRID: 't'
}

const usrLoadWeightUnit = ctx.unitService.getTargetUnitSymbol(loadWeightUnit);

const loadWeightValue = ctx.unitService.convertUnitValue(data?.loadWeight || 0, usrLoadWeightUnit).toFixed(1);

return `
    <div style="
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 16px;
    ">
        <span style="
            font-weight: bold;
            font-size: 16px;
        ">${data.entityName ? data.entityName : ''}</span>
    </div>

    <div style="
        font-size: 14px;
        line-height: 1.8;
        color: #555;
    ">
        <div>
            <b style="font-weight: 600; color: #333;">Lattitude:</b> ${data.latitude}
        </div>
        <div>
            <b style="font-weight: 600; color: #333;">Longtitude:</b> ${data.longitude}
        </div>
        <div>
            <b style="font-weight: 600; color: #333;">Fuel level:</b> ${data.fuelLevel} %
        </div>
        <div>
            <b style="font-weight: 600; color: #333;">Speed:</b> ${speedValue} ${usrSpeedUnit}
        </div>
        <div>
            <b style="font-weight: 600; color: #333;">Load weight:</b> ${loadWeightValue} ${usrLoadWeightUnit}
        </div>
    </div>

    <div style="margin-top: 20px;">
        <button-act name='bus-details' style="
            display: block;
            width: 100%;
            padding: 10px 0;
            text-align: center;
            color: #009688;
            border: 1px solid #009688;
            border-radius: 4px;
            background-color: #fff;
            font-weight: 600;
            font-size: 14px;
            cursor: pointer;
            text-decoration: none;
            box-sizing: border-box;
        ">See details</button-act>
    </div>

`;

